/**
 * Normalise a caught error to an HTTP status, or null.
 *
 * ⛔ The `httpCode` term is load-bearing, NOT defensive padding. For 401/402/403/429
 * RetryingRequest rethrows a `NodeApiError`, which declares
 * `httpCode: string | null` and sets NEITHER `statusCode` NOR `response` (measured
 * against n8n-workflow 1.120.20). A lone `.statusCode` read therefore returns null for
 * PRECISELY the access-denied case this discriminator exists to expose.
 * `.response.status` covers the raw-axios shape, which is what reaches here for every
 * other status.
 *
 * ⚠️ `null` is a THIRD value, not a status: a transport or pre-send failure (DNS, TLS,
 * socket, a throw before the request left) carries no status at all.
 */
function errorStatusCode(error: any): number | null {
  return Number(error?.statusCode ?? error?.httpCode ?? error?.response?.status) || null;
}

/**
 * The upstream body's machine-readable code, or null. First non-nullish of
 * `error_code`, `details.error_code`, `code`, `error.code` — in that order, and ONLY
 * a non-empty string counts. The `??` chain is deliberate: a body that carries
 * `error_code` (or `details.error_code`) resolves exactly as it did before `code` /
 * `error.code` were added. Those two arms exist for services that never send
 * `error_code`: fr's AppError bodies carry top-level `code`, its integration errors a
 * nested `error.code`.
 *
 * ⛔ TOTAL try/catch is load-bearing: this runs INSIDE an error handler, so anything
 * thrown here would replace a clean typed failure with an unhandled crash.
 *
 * ⛔ `.error` IS WHERE n8n PUTS THE BODY. `ctx.helpers.request` -> proxyRequestToAxios
 * throws Object.assign(error, { statusCode, error: responseData, response:
 * pick(response, ["headers","status","statusText"]) } ) — `response` is picked down to
 * three keys with NO body and NO data. `.error` goes LAST so an explicit body wins
 * where one exists.
 *
 * ⚠️ 401/402/403/429: the generated RetryingRequest rethrows these as `NodeApiError`,
 * which DROPS the original error and its body (measured, n8n-workflow 1.120.31: no
 * `.error`, `.cause` or `.errorResponse` survives). In a module whose
 * helpers/RetryingRequest.ts is GENERATED, the operations index puts a COPY of the
 * upstream body back on `.error` for exactly those four statuses
 * (BodyCarryingAuthenticator), so `errorCode` is reachable there — for ops dispatched
 * through executeOperation; a hand-written handler that builds its own
 * RetryingRequest bypasses the carry. In a module whose authenticator is HAND-OWNED
 * (services.json handOwnedFiles) there is NO carry: that file may drop bodies on purpose
 * (n8n-nodes-workers redacts every status, because a 422 can echo a tenant secret), so
 * `errorCode` is whatever that file leaves on the error — null wherever it redacts.
 *
 * ⚠️ A gateway-minted error is NOT null when the gateway sends a code. coding-gateway's
 * `_proxy_error` answers `{"error": {"code": "HTTP_<status>", ...}}` (400 bad path, 404
 * no route, 502 unreachable/too large, 504 timeout), which the `error.code` arm reads as
 * e.g. `"HTTP_502"`: that names the GATEWAY's failure, not the upstream service's.
 *
 * ⚠️ Absence is NOT a verdict. A licence ext-authz denial minted at the ingress, or an
 * istio-minted 502/503/504, carries no code, so `null` means "no code was sent", never
 * "the resource is fine" — read a 401/403 with a null `errorCode` as "could not look".
 */
function errorUpstreamCode(error: any): string | null {
  try {
    let body: any = error?.response?.body ?? error?.response?.data ?? error?.body ?? error?.error;
    if (typeof body === "string") {
      const trimmed = body.trim();
      if (!trimmed) return null;
      try {
        body = JSON.parse(trimmed);
      } catch {
        return null;
      }
    }
    const code = body?.error_code ?? body?.details?.error_code ?? body?.code ?? body?.error?.code;
    return typeof code === "string" && code.length > 0 ? code : null;
  } catch {
    return null;
  }
}

/**
 * The error a repeated, already-rejected call throws instead of being sent
 * (helpers/repeatRejection.ts). Rebuilt from the first call's remembered fields:
 * the same message, `httpCode` = the first status (errorStatusCode reads it), and the
 * upstream code and `details` put back on `.error` so errorUpstreamCode (and a
 * module's validationDetail) read what they read the first time. The first error object itself is not kept (request options, body).
 */
function rejectionError(ctx: IExecuteFunctions, prior: Rejection): NodeApiError {
  const error = new NodeApiError(
    ctx.getNode(),
    { message: prior.message, httpCode: String(prior.status) } as JsonObject,
    { message: prior.message, httpCode: String(prior.status) },
  );
  if (prior.errorCode !== null || prior.details !== null) {
    (error as unknown as { error: unknown }).error = {
      ...(prior.errorCode !== null ? { error_code: prior.errorCode } : {}),
      ...(prior.details !== null ? { details: prior.details } : {}),
    };
  }
  return error;
}

export class Artifacts implements INodeType {
  description: INodeTypeDescription = {
    displayName: "Artifacts",
    name: "artifacts",
    icon: "fa:archive",
    group: ["transform"],
    version: [1, 2],
    subtitle: '={{$parameter["operation"]}}',
    description: "Manage artifacts in Artifact Service",
    defaults: { name: "Artifacts" },
    inputs: ["main"],
    outputs: ["main"],
    usableAsTool: true,
    credentials: [{ name: "artifactsApi", required: true }],
    // Same-named collections (one per resource) are merged into one
    // definition at load time — see helpers/mergeSameNameCollections.ts.
    properties: mergeSameNameCollections([
      artifactsOperations,
      ...artifactsFields,
    ]),
  };

  async execute(this: IExecuteFunctions): Promise<INodeExecutionData[][]> {
    const items = this.getInputData();
    const returnData: INodeExecutionData[] = [];

    const credentials = await this.getCredentials("artifactsApi");
    const baseUrl = resolveBaseUrl(credentials.baseUrl);
    const apiToken = credentials.apiToken as string;

    if (!apiToken) {
      throw new NodeOperationError(
        this.getNode(),
        "API token required. Add in credentials.",
      );
    }

    // The AI-tool variant answers a repeated rejected call with a terminal tool result
    // instead of an error (helpers/repeatRejection.ts).
    const toolRun = isToolRun(this, "artifacts");

    // ⛔ X-Tenant-Id IS THIS SERVICE'S AUTH HEADER, NOT A ROUTING HINT. It reads the licence
    // from `X-Tenant-Id` only; omitting the header does not "let the service introspect the
    // Bearer" — it lands on the trusted-network branch scoped to the SYSTEM tenant
    // (services.json licenceAuth "tenant-header-fallback"; n8n-nodes-procedures#21).
    // A configured tenantId wins and is sent bare; otherwise the licence. Never absent.
    const tenantId = (credentials.tenantId as string) || "";
    const headers: Record<string, string> = {
      Authorization: `Bearer ${apiToken}`,
    };
    headers["X-Tenant-Id"] = tenantId ? tenantId : `Bearer ${apiToken}`;

    for (let i = 0; i < items.length; i++) {
      const resource = "artifacts";
      const operation = this.getNodeParameter("operation", i) as string;
      // Repeat hard stop (helpers/repeatRejection.ts): this exact input already got an
      // input-rejection 4xx in THIS execution ⇒ it is not sent again.
      const rejectionKey = repeatRejectionKey(this, resource, operation, i);
      try {
        const prior = priorRejection(rejectionKey);
        if (prior !== undefined) {
          if (toolRun) {
            returnData.push({ json: terminalToolResult(prior) as unknown as IDataObject, pairedItem: { item: i } });
            continue;
          }
          throw rejectionError(this, prior);
        }
        const responseData = await executeOperation(this, baseUrl, headers, resource, operation, i);
        forgetRejections(this);
        const result = responseData as IDataObject;
        if (Array.isArray(result)) {
          returnData.push(
            ...result.map((item) => ({
              json: item as IDataObject,
              pairedItem: { item: i },
            })),
          );
        } else {
          returnData.push({ json: result, pairedItem: { item: i } });
        }
      } catch (error: unknown) {
        recordRejection(rejectionKey, errorStatusCode(error), error, errorUpstreamCode(error));
        if (this.continueOnFail()) {
          returnData.push({
            json: {
              error: error instanceof Error ? error.message : String(error),
              resource,
              operation,
              // Discriminators (see errorStatusCode/errorUpstreamCode above):
              // "does not exist" (404) vs "could not look" (401/403/5xx/transport).
              statusCode: errorStatusCode(error),
              errorCode: errorUpstreamCode(error),
            } as IDataObject,
            pairedItem: { item: i },
          });
          continue;
        }
        throw new NodeOperationError(
          this.getNode(),
          error instanceof Error ? error : new Error(String(error)),
          { itemIndex: i },
        );
      }
    }

    return [returnData];
  }
}
